// Copies the approved site's static assets (CSS, JS, images, documents, media, robots, _headers)
// from ../public into public/. HTML pages are served by EmDash routes instead; _redirects is
// generated by build-redirects.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.resolve(root, '../public');
const dest = path.join(root, 'public');
let n = 0;
for (const name of fs.readdirSync(src)) {
  if (name.endsWith('.html') || name === '_redirects') continue;
  fs.cpSync(path.join(src, name), path.join(dest, name), { recursive: true });
  n++;
}
console.log(`copied ${n} entries from ../public`);
